arguments.command:
awk -F, -v OFS=, '{
  if (NR==1) { print "checksum",$0; next }
  h = 5381
  for (i=1; i<=NF; i++) {
    s = $i
    for (j=1; j<=length(s); j++) {
      h = (h * 33) + ord(substr(s,j,1))
    }
    h = (h * 33) + 44
  }
  h = h % 2147483647
  print h, $0
}
function ord(c,  i) {
  if (ord_tab == "") for (i=1; i<=127; i++) ord_tab = ord_tab sprintf("%c", i)
  return index(ord_tab, c)
}' data.csv > data.tmp && mv data.tmp data.csv && cat data.csv
